// Verifier-layer test for the reef player's FRAME-IDENTITY contract.
//
// reef/index.html is a satellite coral-reef flicker loop with a pause-to-cull
// feature: deleting a frame persists across reloads via localStorage. The persisted
// identity is `frameKey(f)` = `${name}|${lat.toFixed(3)}|${lon.toFixed(3)}|${z}`, and
// the catalog is generated by `expand(REEFS)` (4 variants per reef: base, zoom-in,
// pan-NE, pan-SW). The load-bearing contract is:
//
//   EVERY frame in the whole catalog must map to a UNIQUE frameKey.
//
// If two distinct frames ever collide on one key, then deleting one frame silently
// deletes the OTHER too (and resurrecting one resurrects the other) — because the
// persisted kill-set is keyed by that string. The collision-freedom is NOT obvious:
// it depends on (a) `frameKey` including BOTH z and the rounded lat/lon, and (b)
// `expand`'s pan delta (0.55 / 2^(z-9)) staying large enough to survive .toFixed(3)
// rounding at every zoom level in the catalog. Either could drift in a future edit.
//
// This test EXTRACTS the real shipped REEFS / expand / frameKey from index.html at
// runtime (regex + new Function) so it cannot fall out of sync with a hand-copy.
// Mutation-proven below: dropping z from the key, or zeroing the pan delta, makes the
// catalog collide — the negative assertions at the bottom verify the test has teeth.

import { readFileSync } from 'node:fs';
import { strict as assert } from 'node:assert';

const html = readFileSync(new URL('./index.html', import.meta.url), 'utf8');

function grab(re, label) {
  const m = html.match(re);
  assert.ok(m, `could not find ${label} in reef/index.html`);
  return m[0];
}

function loadCatalog(frameKeySrc) {
  const REEFS = grab(/const REEFS = \[[\s\S]*?\n\];/, 'REEFS');
  const expand = grab(/function expand\(reefs\) \{[\s\S]*?\n\}/, 'expand()');
  const fk = frameKeySrc ?? grab(/const frameKey = .*/, 'frameKey');
  const mod = new Function(`${REEFS}\n${expand}\n${fk}\nreturn { REEFS, expand, frameKey };`)();
  return { ...mod, frames: mod.expand(mod.REEFS) };
}

let passed = 0;
const ok = (cond, msg) => { assert.ok(cond, msg); passed++; };
const eq = (a, b, msg) => { assert.equal(a, b, msg); passed++; };

const { REEFS, expand, frameKey, frames } = loadCatalog();

// --- 1. catalog fan-out: exactly 4 variants per reef ---
eq(frames.length, REEFS.length * 4, 'expand() must emit exactly 4 frames per reef');
ok(REEFS.length > 0, 'catalog is non-empty');

// --- 2. THE load-bearing contract: every frame has a unique persisted key ---
const keys = frames.map(frameKey);
const uniq = new Set(keys);
eq(uniq.size, keys.length,
  'frameKey must be unique for every frame — a collision means deleting one frame deletes another');

// --- 3. the 4 variants of a single reef are all distinct keys ---
const [name0, lat0, lon0, z0] = REEFS[0];
const variants = expand([[name0, lat0, lon0, z0]]);
eq(variants.length, 4, 'one reef expands to 4 variants');
eq(new Set(variants.map(frameKey)).size, 4, 'all 4 variants of a reef must have distinct keys');
// base + zoom share lat/lon but differ in z; the two pans differ in lat/lon
ok(variants.some(v => v.z === z0) && variants.some(v => v.z === z0 + 1),
  'expand() must include a base zoom and a zoom-in variant');
const lats = new Set(variants.map(v => v.lat.toFixed(3)));
ok(lats.size >= 3, 'the pan variants must actually move lat/lon (distinct at 3dp), not collapse onto base');

// --- 4. key is content-addressed: independent of array order (survives the load shuffle) ---
// The page shuffles FRAMES with Math.random each load; persistence only works if the key
// depends on the frame's content, not its index. Same frame object -> same key, always.
const f = frames[Math.floor(frames.length / 2)];
eq(frameKey(f), frameKey({ ...f }), 'frameKey must be a pure function of frame content');
eq(frameKey(f), `${f.name}|${f.lat.toFixed(3)}|${f.lon.toFixed(3)}|${f.z}`,
  'frameKey format is the persisted contract — changing it resurrects every deleted frame');

// --- 5. MUTATION PROOF: neutering either guard reintroduces collisions ---
// (a) drop z from the key -> base and zoom-in variant (same name/lat/lon) collide.
const noZ = loadCatalog('const frameKey = (f) => `${f.name}|${f.lat.toFixed(3)}|${f.lon.toFixed(3)}`;');
const noZkeys = noZ.frames.map(noZ.frameKey);
ok(new Set(noZkeys).size < noZkeys.length,
  'sanity: a frameKey WITHOUT z must collide (proves including z is load-bearing)');

// (b) the real frameKey over a zero-pan catalog collides -> the pan delta is load-bearing.
// Rebuild expand with d=0 so every pan variant lands on the base coords.
const zeroPanExpand = expand.toString().replace('0.55 / Math.pow(2, z - 9)', '0');
const zp = new Function(
  `const REEFS = ${JSON.stringify(REEFS)};\n` +
  `const expandZ = ${zeroPanExpand.replace('function expand', 'function expandZ')};\n` +
  grab(/const frameKey = .*/, 'frameKey') + '\n' +
  `return expandZ(REEFS).map(frameKey);`
)();
ok(new Set(zp).size < zp.length,
  'sanity: a zero pan-delta must collide (proves expand()\'s pan offset is load-bearing)');

console.log(`frame-identity.test.mjs: ${passed} passed, 0 failed`);
